begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000000631','image-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000000632','image-outsider@example.test',now()),
 ('f0000000-0000-4000-8000-000000000633','catalog-bot@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000631","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Image test','image-test',gen_random_uuid())::text,true);
select set_config('test.merchant',gen_random_uuid()::text,true);
select enable_zettle_pull(current_setting('test.tenant')::uuid,current_setting('test.merchant')::uuid);
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy')||'{"vatModeConsignmentPrivate":"consignment_margin"}');
select publish_zettle_catalog_config(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'{"consignment_margin":0}');
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','image-seller@example.test','')::text,true);
select set_config('test.agreement',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'Synthetic terms','Test only','en',false)::text,true);
select record_agreement_evidence(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.agreement')::uuid,'Test evidence');
select set_config('test.session',create_reception_session(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid)::text,true);
select set_config('test.photo',gen_random_uuid()::text,true);
select set_config('test.path',current_setting('test.tenant')||'/'||current_setting('test.session')||'/'||current_setting('test.photo')||'.jpg',true);
reset role;
insert into storage.objects(bucket_id,name) values('reception-photos',current_setting('test.path'));
set local role authenticated;
select save_reception_sources(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session')::uuid,0,jsonb_build_array(jsonb_build_object('id',current_setting('test.photo'),'kind','photo','reference',current_setting('test.path'),'observation',''),jsonb_build_object('id','f0000000-0000-4000-8000-000000000638','kind','price-evidence','reference','Staff','observation','Test appraisal')));
select publish_reception_review(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session')::uuid,1,null,current_setting('test.agreement')::uuid,jsonb_build_object('attributes',jsonb_build_array(jsonb_build_object('slug','description','definitionVersion',1,'value','Test jacket','sourceIds',jsonb_build_array(current_setting('test.photo')),'certainty','observed')),'price',jsonb_build_object('currency','SEK','amount','100.00','rationale','Test','sourceIds',jsonb_build_array('f0000000-0000-4000-8000-000000000638'::text)),'questions','[]'::jsonb),now()+interval '1 day');
select receive_garment(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session')::uuid,'');
select set_config('test.item',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid,'reception_review',current_setting('test.session')::uuid,1,10000);

select is(catalog_automation_status(current_setting('test.tenant')::uuid,'paypal')->>'enabled','false','automatic export defaults off');
select enable_automation(current_setting('test.tenant')::uuid,gen_random_uuid(),'zettle_pull','catalog-bot@example.test');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000633","role":"authenticated"}';
select accept_automation_grants();
select throws_like($$select prepare_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid)$$,'%FORBIDDEN%','receipt grant cannot write catalog');
select throws_like($$select claim_catalog_export(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal')$$,'%FORBIDDEN%','receipt grant cannot claim export');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000631","role":"authenticated"}';
select disable_automation(current_setting('test.tenant')::uuid,'zettle_pull');
select set_config('test.binding',gen_random_uuid()::text,true);
select save_catalog_automation(current_setting('test.tenant')::uuid,current_setting('test.binding')::uuid,'paypal',current_setting('test.merchant'),null,true,'catalog-bot@example.test');
select lives_ok($$select save_catalog_automation(current_setting('test.tenant')::uuid,current_setting('test.binding')::uuid,'paypal',current_setting('test.merchant'),null,true,'catalog-bot@example.test')$$,'setting replay is idempotent');
select throws_like($$select save_catalog_automation(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal',current_setting('test.merchant'),null,false,null)$$,'%SYNC_SETTINGS_CHANGED%','stale setting cannot overwrite activation');
select throws_like($$select save_catalog_automation(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal','wrong',null,true,'catalog-bot@example.test')$$,'%SYNC_CONNECTION_CHANGED%','account checked');
select throws_like($$select save_catalog_automation(current_setting('test.tenant')::uuid,gen_random_uuid(),'shopify','wrong',null,true,'catalog-bot@example.test')$$,'%INVALID_INPUT%','unsupported adapter cannot activate');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000633","role":"authenticated"}';
select accept_automation_grants();
select throws_like($$select prepare_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid)$$,'%FORBIDDEN%','accepted catalog grant without lease cannot export');
select set_config('test.expired',gen_random_uuid()::text,true);
reset role;
insert into catalog_export_jobs(id,tenant_id,provider,connection_ref,item_id,binding_id,created_by,started_at,lease_until)
 values(current_setting('test.expired')::uuid,current_setting('test.tenant')::uuid,'paypal',current_setting('test.merchant'),current_setting('test.item')::uuid,current_setting('test.binding')::uuid,'f0000000-0000-4000-8000-000000000633',clock_timestamp()-interval '2 hours',clock_timestamp()-interval '1 hour');
set local role authenticated;
select is(catalog_export_item_access(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid),false,'expired lease cannot export');
select throws_like($$select read_paypal_credentials(current_setting('test.tenant')::uuid)$$,'%FORBIDDEN%','expired lease cannot read credentials');
select set_config('test.job',gen_random_uuid()::text,true);
select is(claim_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'paypal')->>'itemId',current_setting('test.item'),'job selects unsent saleable item');
select throws_like($$select finish_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.expired')::uuid,'complete')$$,'%FORBIDDEN%','new lease cannot finish expired job');
select is(claim_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'paypal'),null::jsonb,'lost claim grants no second execution');
select is(claim_catalog_export(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal'),null::jsonb,'active job prevents competing job');
select is(catalog_export_item_access(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid),true,'leased item authorized');
select is(catalog_export_item_access(current_setting('test.tenant')::uuid,gen_random_uuid()),false,'other item denied');
select is(catalog_export_item_access(current_setting('test.tenant')::uuid,null),false,'null item denied');
select is(catalog_export_item_access(gen_random_uuid(),current_setting('test.item')::uuid),false,'other tenant denied');
select throws_like($$select paypal_item_status(current_setting('test.tenant')::uuid,null)$$,'%FORBIDDEN%','null list cannot bypass item permission');
select throws_like($$select paypal_item_status(current_setting('test.tenant')::uuid,array[current_setting('test.item')::uuid,gen_random_uuid()])$$,'%FORBIDDEN%','status limited to leased item');
select set_config('test.export',prepare_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid)::text,true);
select is(catalog_export_payload(current_setting('test.tenant')::uuid,current_setting('test.export')::uuid)->'payload'->>'externalReference','komisio:'||current_setting('test.item'),'scoped payload available');
select is((select count(*) from zettle_product_exports),0::bigint,'worker cannot select private export table');
select lives_ok($$select finish_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.export')::uuid,'synced',null)$$,'scoped worker records product outcome');
select set_config('test.locations',jsonb_build_object('STORE',gen_random_uuid(),'SUPPLIER',gen_random_uuid(),'SOLD',gen_random_uuid(),'BIN',gen_random_uuid())::text,true);
select is(claim_zettle_stock(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.export')::uuid,current_setting('test.merchant')::uuid,current_setting('test.locations')::jsonb)->>'fresh','true','first lifetime stock claim granted');
select is(claim_zettle_stock(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.export')::uuid,current_setting('test.merchant')::uuid,current_setting('test.locations')::jsonb)->>'fresh','false','retry cannot add stock twice');
select finish_zettle_stock(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'initialized',null);
select throws_like($$select prepare_zettle_image(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,current_setting('test.merchant')::uuid)$$,'%FORBIDDEN%','automation cannot bypass disabled image preference');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000631","role":"authenticated"}';
select set_config('test.preference',gen_random_uuid()::text,true);
select save_integration_sync_preference(current_setting('test.tenant')::uuid,current_setting('test.preference')::uuid,'paypal',current_setting('test.merchant'),null,true);
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000633","role":"authenticated"}';
select is(prepare_zettle_sync_image(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,current_setting('test.item')::uuid,current_setting('test.merchant')::uuid)->>'fresh','true','worker receives one image upload claim');
select lives_ok($$select record_zettle_image_upload(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'https://image.izettle.com/product/automatic.jpg')$$,'worker records uploaded image');
select lives_ok($$select finish_zettle_image(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid)$$,'worker records association');
select finish_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'complete');
select lives_ok($$select finish_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'complete')$$,'finished outcome replays');
select throws_like($$select finish_catalog_export(current_setting('test.tenant')::uuid,current_setting('test.job')::uuid,'failed')$$,'%REQUEST_CONFLICT%','finished outcome immutable');
select is(catalog_export_item_access(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid),false,'completed job closes permissions');
select is(claim_catalog_export(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal'),null::jsonb,'synced item not exported again');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000631","role":"authenticated"}';
reset role;
insert into catalog_export_jobs(id,tenant_id,provider,connection_ref,item_id,binding_id,created_by)
 values(gen_random_uuid(),current_setting('test.tenant')::uuid,'paypal',current_setting('test.merchant'),current_setting('test.item')::uuid,current_setting('test.binding')::uuid,'f0000000-0000-4000-8000-000000000633');
set local role authenticated;
select save_catalog_automation(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal',current_setting('test.merchant'),current_setting('test.binding')::uuid,false,null);
select is(catalog_automation_status(current_setting('test.tenant')::uuid,'paypal')->>'enabled','false','owner can disable');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000633","role":"authenticated"}';
select throws_like($$select claim_catalog_export(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal')$$,'%FORBIDDEN%','disabled binding cannot claim');
select is(catalog_export_item_access(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid),false,'revocation closes existing live lease');
select throws_like($$select prepare_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid)$$,'%FORBIDDEN%','revocation stops further adapter calls');
select throws_like($$select read_paypal_credentials(current_setting('test.tenant')::uuid)$$,'%FORBIDDEN%','revocation stops credential reads');
select throws_like($$insert into catalog_export_jobs(id,tenant_id,provider,connection_ref,item_id,binding_id,created_by) values(gen_random_uuid(),current_setting('test.tenant')::uuid,'paypal',current_setting('test.merchant'),current_setting('test.item')::uuid,current_setting('test.binding')::uuid,auth.uid())$$,'%permission denied%','no direct job writes');
select * from finish();rollback;
